chunks = [
    {"id": "c1", "tenant": "acme", "text": "Acme's Falcon plan costs twenty dollars."},
    {"id": "c2", "tenant": "globex", "text": "Globex's Falcon plan costs thirty dollars."},
]

response_cache = {}

def tenant_scoped_retrieve(query, tenant_id):
    # cross-tenant queries must never leak
    return [c for c in chunks if c["tenant"] == tenant_id]

def get_cached_response(query, tenant_id):
    # tenant-scoped cache key
    cache_key = (query.strip().lower(), tenant_id)
    return response_cache.get(cache_key)

def set_cached_response(query, tenant_id, value):
    cache_key = (query.strip().lower(), tenant_id)
    response_cache[cache_key] = value

query = "What does the Falcon plan cost?"

for tenant in ["acme", "globex"]:
    retrieved = tenant_scoped_retrieve(query, tenant)
    print(f"Tenant '{tenant}' retrieves: {[c['id'] for c in retrieved]}")
    set_cached_response(query, tenant, f"Answer for {tenant}: {retrieved[0]['text']}")

print(f"\nAcme's cached response: {get_cached_response(query, 'acme')}")
print(f"Globex's cached response: {get_cached_response(query, 'globex')}")
